1: /**
2:  * Domain vocabulary and calendar arithmetic for the New Stats screen.
3:  *
4:  * This module owns every rule that is true regardless of transport, storage or
5:  * UI: which metrics a chart can render for a given period window, how rolling
6:  * windows and calendar periods are described, and how paging one period moves
7:  * the window while preserving the semantic origin the user picked.
8:  */
9: 
10: /** Metrics the stats charts and summary rows can be expressed in. */
11: export enum NewStatsMetric {
12:   VIEWS = 'views',
13:   VISITORS = 'visitors',
14:   LIKES = 'likes',
15:   COMMENTS = 'comments',
16:   POSTS = 'posts'
17: }
18: 
19: /**
20:  * How a period window derives its concrete dates.
21:  *
22:  * ROLLING windows move with the clock, CALENDAR periods snap to calendar
23:  * boundaries, and CUSTOM windows come from drilling into a single bucket.
24:  * The distinction is what stops a paged rolling window from silently turning
25:  * into a calendar period when its dates happen to line up.
26:  */
27: export enum NewStatsPeriodKind {
28:   ROLLING = 'rolling',
29:   CALENDAR = 'calendar',
30:   CUSTOM = 'custom'
31: }
32: 
33: /** Origin identifiers the period selector offers. */
34: export enum NewStatsPeriodType {
35:   TODAY = 'today',
36:   YESTERDAY = 'yesterday',
37:   LAST_7_DAYS = 'last_7_days',
38:   LAST_30_DAYS = 'last_30_days',
39:   LAST_90_DAYS = 'last_90_days',
40:   THIS_WEEK = 'this_week',
41:   THIS_MONTH = 'this_month',
42:   THIS_YEAR = 'this_year'
43: }
44: 
45: /** Coarse rendering states shared by the chart and the cards around it. */
46: export enum NewStatsContentState {
47:   LOADING = 'loading',
48:   LOADED = 'loaded',
49:   EMPTY = 'empty',
50:   /** The chosen metric cannot be drawn for the current window. */
51:   METRIC_UNAVAILABLE = 'metric_unavailable',
52:   ERROR = 'error',
53:   PLAN_GATED = 'plan_gated',
54:   AUTH_ERROR = 'auth_error'
55: }
56: 
57: /** Which grouping the "Visitors by location" card is showing. */
58: export enum NewStatsLocationType {
59:   COUNTRIES = 'countries',
60:   REGIONS = 'regions'
61: }
62: 
63: /** A resolved period window together with the origin that produced it. */
64: export interface NewStatsPeriod {
65:   kind: string;
66:   /** Always 'custom' in persisted form; the concrete range is what is stored. */
67:   type: string;
68:   origin: string;
69:   start: string;
70:   end: string;
71: }
72: 
73: /** One bucket of a chart series. */
74: export interface NewStatsBucket {
75:   index: number;
76:   rawPeriod: string;
77:   label: string;
78:   isUpcoming: boolean;
79:   canDrillDown: boolean;
80:   views: number;
81:   visitors: number;
82:   likes: number;
83:   comments: number;
84:   posts: number;
85: }
86: 
87: const MILLIS_PER_DAY: number = 86400000;
88: const ISO_LENGTH: number = 10;
89: 
90: /** Proleptic Gregorian day, kept independent of the device time zone. */
91: export class NewStatsDay {
92:   year: number;
93:   month: number;
94:   day: number;
95: 
96:   constructor(year: number, month: number, day: number) {
97:     this.year = year;
98:     this.month = month;
99:     this.day = day;
100:   }
101: }
102: 
103: function pad2(value: number): string {
104:   const text: string = value.toString();
105:   return text.length < 2 ? '0' + text : text;
106: }
107: 
108: function pad4(value: number): string {
109:   const text: string = value.toString();
110:   return text.length < 4 ? '0000'.substring(text.length) + text : text;
111: }
112: 
113: export function formatNewStatsDay(value: NewStatsDay): string {
114:   return pad4(value.year) + '-' + pad2(value.month) + '-' + pad2(value.day);
115: }
116: 
117: export function parseNewStatsDay(text: string): NewStatsDay {
118:   if (text.length < ISO_LENGTH) {
119:     return new NewStatsDay(1970, 1, 1);
120:   }
121:   const year: number = parseInt(text.substring(0, 4));
122:   const month: number = parseInt(text.substring(5, 7));
123:   const day: number = parseInt(text.substring(8, 10));
124:   return new NewStatsDay(year, month, day);
125: }
126: 
127: export function newStatsEpochDay(value: NewStatsDay): number {
128:   return Math.floor(Date.UTC(value.year, value.month - 1, value.day) / MILLIS_PER_DAY);
129: }
130: 
131: export function newStatsDayFromEpoch(epoch: number): NewStatsDay {
132:   const instant: Date = new Date(epoch * MILLIS_PER_DAY);
133:   return new NewStatsDay(instant.getUTCFullYear(), instant.getUTCMonth() + 1, instant.getUTCDate());
134: }
135: 
136: export function newStatsToday(): string {
137:   const now: Date = new Date();
138:   return formatNewStatsDay(new NewStatsDay(now.getFullYear(), now.getMonth() + 1, now.getDate()));
139: }
140: 
141: export function addNewStatsDays(day: string, delta: number): string {
142:   return formatNewStatsDay(newStatsDayFromEpoch(newStatsEpochDay(parseNewStatsDay(day)) + delta));
143: }
144: 
145: export function diffNewStatsDays(from: string, to: string): number {
146:   return newStatsEpochDay(parseNewStatsDay(to)) - newStatsEpochDay(parseNewStatsDay(from));
147: }
148: 
149: /** Monday-based, matching the stats calendar in the WordPress clients. */
150: export function startOfNewStatsWeek(day: string): string {
151:   const epoch: number = newStatsEpochDay(parseNewStatsDay(day));
152:   const weekday: number = ((epoch + 3) % 7 + 7) % 7;
153:   return formatNewStatsDay(newStatsDayFromEpoch(epoch - weekday));
154: }
155: 
156: export function endOfNewStatsWeek(day: string): string {
157:   return addNewStatsDays(startOfNewStatsWeek(day), 6);
158: }
159: 
160: export function startOfNewStatsMonth(day: string): string {
161:   const value: NewStatsDay = parseNewStatsDay(day);
162:   return formatNewStatsDay(new NewStatsDay(value.year, value.month, 1));
163: }
164: 
165: export function endOfNewStatsMonth(day: string): string {
166:   const value: NewStatsDay = parseNewStatsDay(day);
167:   const nextMonth: number = newStatsEpochDay(new NewStatsDay(value.year, value.month + 1, 1));
168:   return formatNewStatsDay(newStatsDayFromEpoch(nextMonth - 1));
169: }
170: 
171: export function startOfNewStatsYear(day: string): string {
172:   const value: NewStatsDay = parseNewStatsDay(day);
173:   return formatNewStatsDay(new NewStatsDay(value.year, 1, 1));
174: }
175: 
176: export function endOfNewStatsYear(day: string): string {
177:   const value: NewStatsDay = parseNewStatsDay(day);
178:   return formatNewStatsDay(new NewStatsDay(value.year, 12, 31));
179: }
180: 
181: /**
182:  * Resolve an origin into a concrete window for a given "today".
183:  * The origin name is preserved on the result so paging and restoration can
184:  * keep the period's meaning instead of re-deriving it from the dates.
185:  */
186: export function resolveNewStatsPeriod(origin: string, today: string): NewStatsPeriod {
187:   const yesterday: string = addNewStatsDays(today, -1);
188:   let kind: string = NewStatsPeriodKind.ROLLING;
189:   let start: string = today;
190:   let end: string = today;
191: 
192:   if (origin === NewStatsPeriodType.YESTERDAY) {
193:     start = yesterday;
194:     end = yesterday;
195:   } else if (origin === NewStatsPeriodType.LAST_7_DAYS) {
196:     start = addNewStatsDays(today, -6);
197:     end = today;
198:   } else if (origin === NewStatsPeriodType.LAST_30_DAYS) {
199:     start = addNewStatsDays(today, -29);
200:     end = today;
201:   } else if (origin === NewStatsPeriodType.LAST_90_DAYS) {
202:     start = addNewStatsDays(today, -89);
203:     end = today;
204:   } else if (origin === NewStatsPeriodType.THIS_WEEK) {
205:     kind = NewStatsPeriodKind.CALENDAR;
206:     start = startOfNewStatsWeek(today);
207:     end = endOfNewStatsWeek(today);
208:   } else if (origin === NewStatsPeriodType.THIS_MONTH) {
209:     kind = NewStatsPeriodKind.CALENDAR;
210:     start = startOfNewStatsMonth(today);
211:     end = endOfNewStatsMonth(today);
212:   } else if (origin === NewStatsPeriodType.THIS_YEAR) {
213:     kind = NewStatsPeriodKind.CALENDAR;
214:     start = startOfNewStatsYear(today);
215:     end = endOfNewStatsYear(today);
216:   }
217:   return { kind: kind, type: 'custom', origin: origin, start: start, end: end };
218: }
219: 
220: /** A single-day window is drawn as an hourly series. */
221: export function isHourlyNewStatsPeriod(period: NewStatsPeriod): boolean {
222:   return period.start === period.end;
223: }
224: 
225: function shiftNewStatsPeriod(period: NewStatsPeriod, direction: number): NewStatsPeriod {
226:   if (period.origin === NewStatsPeriodType.THIS_MONTH) {
227:     const value: NewStatsDay = parseNewStatsDay(period.start);
228:     const shifted: NewStatsDay = new NewStatsDay(value.year, value.month + direction, 1);
229:     const anchor: string = formatNewStatsDay(shifted);
230:     return {
231:       kind: period.kind,
232:       type: 'custom',
233:       origin: period.origin,
234:       start: startOfNewStatsMonth(anchor),
235:       end: endOfNewStatsMonth(anchor)
236:     };
237:   }
238:   if (period.origin === NewStatsPeriodType.THIS_YEAR) {
239:     const value: NewStatsDay = parseNewStatsDay(period.start);
240:     const anchor: string = formatNewStatsDay(new NewStatsDay(value.year + direction, 1, 1));
241:     return {
242:       kind: period.kind,
243:       type: 'custom',
244:       origin: period.origin,
245:       start: startOfNewStatsYear(anchor),
246:       end: endOfNewStatsYear(anchor)
247:     };
248:   }
249:   const span: number = diffNewStatsDays(period.start, period.end) + 1;
250:   return {
251:     kind: period.kind,
252:     type: 'custom',
253:     origin: period.origin,
254:     start: addNewStatsDays(period.start, span * direction),
255:     end: addNewStatsDays(period.end, span * direction)
256:   };
257: }
258: 
259: /**
260:  * Paging forward must never carry the window past the present edge.
261:  *
262:  * Landing exactly on today is allowed — that is the window the user is
263:  * normally looking at — so only a window that ends after today is refused.
264:  */
265: function wouldPassPresentEdge(period: NewStatsPeriod, today: string): boolean {
266:   return diffNewStatsDays(period.end, today) > 0;
267: }
268: 
269: export function canPageNewStatsForward(period: NewStatsPeriod, today: string): boolean {
270:   return !wouldPassPresentEdge(shiftNewStatsPeriod(period, 1), today);
271: }
272: 
273: export function canPageNewStatsBackward(period: NewStatsPeriod): boolean {
274:   return true;
275: }
276: 
277: export function pageNewStatsForward(period: NewStatsPeriod, today: string): NewStatsPeriod | undefined {
278:   if (!canPageNewStatsForward(period, today)) {
279:     return undefined;
280:   }
281:   return shiftNewStatsPeriod(period, 1);
282: }
283: 
284: export function pageNewStatsBackward(period: NewStatsPeriod): NewStatsPeriod {
285:   return shiftNewStatsPeriod(period, -1);
286: }
287: 
288: export function newStatsPeriodSpanDays(period: NewStatsPeriod): number {
289:   return diffNewStatsDays(period.start, period.end) + 1;
290: }
291: 
292: const ALL_METRICS: string[] = [
293:   NewStatsMetric.VIEWS,
294:   NewStatsMetric.VISITORS,
295:   NewStatsMetric.LIKES,
296:   NewStatsMetric.COMMENTS,
297:   NewStatsMetric.POSTS
298: ];
299: 
300: /**
301:  * An hourly series only carries views, so a single-day window cannot draw the
302:  * other metrics even though the period itself understands them.
303:  *
304:  * `hourlyMetrics` lets the caller supply the metrics the hourly endpoint
305:  * actually publishes for the site, defaulting to views.
306:  */
307: export function supportedNewStatsChartMetrics(period: NewStatsPeriod, hourlyMetrics?: string[]): string[] {
308:   if (isHourlyNewStatsPeriod(period)) {
309:     return hourlyMetrics !== undefined && hourlyMetrics.length > 0 ? hourlyMetrics : [NewStatsMetric.VIEWS];
310:   }
311:   return ALL_METRICS;
312: }
313: 
314: export function supportsNewStatsChartMetric(period: NewStatsPeriod, metric: string, hourlyMetrics?: string[]): boolean {
315:   return supportedNewStatsChartMetrics(period, hourlyMetrics).indexOf(metric) >= 0;
316: }
317: 
318: /** The summary row keeps working for every metric regardless of chart shape. */
319: export function supportedNewStatsSummaryMetrics(): string[] {
320:   return ALL_METRICS;
321: }
322: 
323: export function isKnownNewStatsMetric(metric: string): boolean {
324:   return ALL_METRICS.indexOf(metric) >= 0;
325: }
326: 
327: /** The metric a chart falls back to when the preference cannot be drawn. */
328: export function fallbackNewStatsMetric(period: NewStatsPeriod, hourlyMetrics?: string[]): string {
329:   const supported: string[] = supportedNewStatsChartMetrics(period, hourlyMetrics);
330:   return supported.length > 0 ? supported[0] : NewStatsMetric.VIEWS;
331: }
332: 
333: export function newStatsMetricValue(source: Record<string, number>, metric: string): number {
334:   const value: number | undefined = source[metric];
335:   return value === undefined ? 0 : value;
336: }
